:root {
  --bg: #f5f6f8;
  --panel: #ffffff;
  --border: #e2e5ea;
  --text: #1c2333;
  --muted: #6b7280;
  --accent: #2563eb;
  --accent-hover: #1d4ed8;
  --danger: #dc2626;
  --tag-bg: #eef2ff;
  --tag-text: #3730a3;
  --radius: 10px;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica,
    Arial, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.5;
}

.app {
  max-width: 760px;
  margin: 0 auto;
  padding: 2rem 1.25rem 4rem;
}

.app-header h1 {
  margin: 0;
  font-size: 1.9rem;
}

.subtitle {
  margin: 0.25rem 0 1.5rem;
  color: var(--muted);
}

.save-panel,
.list-panel {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.25rem;
  margin-bottom: 1.25rem;
}

.save-form {
  display: grid;
  gap: 0.9rem;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
}

.field label {
  font-weight: 600;
  font-size: 0.9rem;
}

.hint {
  color: var(--muted);
  font-weight: 400;
}

input[type="text"],
input[type="search"] {
  padding: 0.6rem 0.7rem;
  border: 1px solid var(--border);
  border-radius: 8px;
  font-size: 1rem;
  width: 100%;
}

input:focus {
  outline: 2px solid var(--accent);
  border-color: var(--accent);
}

button {
  cursor: pointer;
  font-size: 0.95rem;
  border-radius: 8px;
  border: 1px solid transparent;
  padding: 0.6rem 1rem;
  background: var(--accent);
  color: #fff;
  font-weight: 600;
}

button:hover {
  background: var(--accent-hover);
}

button.secondary {
  background: transparent;
  color: var(--accent);
  border-color: var(--border);
  padding: 0.3rem 0.6rem;
  font-size: 0.85rem;
}

button.secondary:hover {
  background: var(--tag-bg);
}

button.link-danger {
  background: transparent;
  color: var(--danger);
  border-color: var(--border);
  padding: 0.3rem 0.6rem;
  font-size: 0.85rem;
}

button.link-danger:hover {
  background: #fee2e2;
}

.form-message {
  margin: 0.8rem 0 0;
  padding: 0.6rem 0.7rem;
  border-radius: 8px;
  font-size: 0.9rem;
}

.form-message.error {
  background: #fee2e2;
  color: var(--danger);
}

.form-message.warn {
  background: #fef3c7;
  color: #92400e;
}

.form-message.success {
  background: #dcfce7;
  color: #166534;
}

.controls {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  margin-bottom: 1rem;
}

.tag-filters {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
}

.tag-filters button {
  background: var(--tag-bg);
  color: var(--tag-text);
  border: 1px solid transparent;
  padding: 0.25rem 0.6rem;
  font-size: 0.82rem;
  font-weight: 500;
}

.tag-filters button[aria-pressed="true"] {
  background: var(--accent);
  color: #fff;
}

.bookmark-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0.75rem;
}

.bookmark {
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 0.85rem 1rem;
}

.bookmark-title {
  font-weight: 600;
  font-size: 1.05rem;
  color: var(--accent);
  text-decoration: none;
  word-break: break-word;
}

.bookmark-title:hover {
  text-decoration: underline;
}

.bookmark-url {
  color: var(--muted);
  font-size: 0.85rem;
  margin: 0.15rem 0 0.5rem;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.bookmark-tags {
